target.css:
:root {
  --ink: #25213d;
  --paper: #fffdf8;
  --violet: #6f4bd8;
  --violet-soft: #eee9ff;
  --lime: #cbf06c;
  --orange: #ff9b5f;
  --line: #ded9ec;
  --muted: #77728c;
}

.wallet {
  box-sizing: border-box;
  width: 470px;
  padding: 14px;
  border: 2px solid var(--ink);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.wallet *,
.wallet *::before,
.wallet *::after {
  box-sizing: border-box;
}

.wallet-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 11px;
  border-bottom: 1px solid var(--line);
}

.brand {
  display: flex;
  align-items: center;
  gap: 9px;
}

.brand-mark {
  display: grid;
  width: 31px;
  height: 31px;
  place-items: center;
  border-radius: 9px;
  background: var(--violet);
  color: var(--lime);
  font-size: 18px;
}

.eyebrow,
.label {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1px;
}

.wallet h1,
.wallet h2,
.wallet p {
  margin-top: 0;
}

.wallet h1 {
  margin-bottom: 0;
  font-size: 18px;
  line-height: 1.15;
}

.wallet time {
  border-radius: 999px;
  background: var(--lime);
  padding: 5px 8px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .4px;
}

.balance {
  display: flex;
  align-items: end;
  justify-content: space-between;
  margin: 11px 0;
  padding: 11px 12px;
  border-radius: 12px;
  background: var(--violet-soft);
}

.ticket-count {
  margin: 2px 0 0;
  font-size: 27px;
  font-weight: 800;
  letter-spacing: -1px;
  line-height: 1;
}

.level {
  display: flex;
  flex-direction: column;
  align-items: end;
  gap: 3px;
  margin: 0;
  color: var(--violet);
  font-size: 11px;
}

.level span {
  border: 1px solid var(--violet);
  border-radius: 999px;
  padding: 2px 6px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .5px;
}

.activity {
  border: 1px solid var(--line);
  border-radius: 12px;
  overflow: hidden;
}

.activity-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 10px;
  background: var(--paper);
}

.activity-header h2 {
  margin: 0;
  font-size: 13px;
}

.activity-header span {
  color: var(--violet);
  font-size: 11px;
  font-weight: 800;
}

.game-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin: 0;
  padding: 0;
  border-top: 1px solid var(--line);
  list-style: none;
}

.game-list li {
  display: grid;
  grid-template-columns: 19px 1fr;
  gap: 2px 5px;
  padding: 8px;
  border-right: 1px solid var(--line);
}

.game-list li:last-child {
  border-right: 0;
}

.game-icon {
  grid-row: span 2;
  color: var(--orange);
  font-size: 18px;
  line-height: 1;
}

.game-name {
  font-size: 11px;
  font-weight: 700;
  line-height: 1;
}

.game-list strong {
  color: var(--violet);
  font-size: 11px;
  line-height: 1;
}

.wallet-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 10px;
}

.wallet-footer p {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
}

.wallet-footer p strong {
  color: var(--ink);
}

.wallet button {
  border: 0;
  border-radius: 8px;
  padding: 7px 10px;
  background: var(--ink);
  color: var(--paper);
  font-size: 11px;
  font-weight: 800;
}

